import{z as n,x as o,o as B,c as i,q as A,j as t,D as a,d as l,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"中途评估的门禁","description":"","frontmatter":{"title":"中途评估的门禁","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-midtrain-eval-gates.md","filePath":"llm/pf2-midtrain-eval-gates.md","lastUpdated":1791063341000}'),C={name:"llm/pf2-midtrain-eval-gates.md"};function p(d,E,F,D,h,m){const e=o("Mermaid");return B(),i("div",null,[E[2]||(E[2]=A('<h1 id="中途评估的门禁" tabindex="-1">中途评估的门禁 <a class="header-anchor" href="#中途评估的门禁" aria-label="Permalink to &quot;中途评估的门禁&quot;">​</a></h1><div class="epigraph"><p>中途评估回答的问题只有一个：这次训练继续、调整还是停下；「这次涨了三分」不是它的问题。</p><footer>—— 据 loss 曲线分期（Kaplan et al., 2020；Nakkiran et al., 2020）与大规模训练的门禁实践整理</footer></div><p><a href="/llm/pf2-longrun-health">上一课</a>管的是信号健康：这一步有没有问题。本课把观测升到决策层：训练进行到几万亿 token 的中途，用什么评估、按什么判据决定继续或调整。<a href="/llm/loss-curve-phases">loss 曲线的分期</a>已说明终点 CE 不等于已学会；本课写的是在环内的低频决策点——门禁的判据怎么预注册、评估作业怎么保证不改训练轨迹、什么情况允许动配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中途评估有两种失败。一种是<strong>没有</strong>：全程只看训练 CE，几周后发现下游能力结构不对——数学塌了或代码没起来——此时已无中途可言，只剩重来。另一种是<strong>太热闹</strong>：每五百亿 token 跑全量榜单，看到分数起伏就当场调配比、换学习率，把一次训练拆成几十次无对照的临时实验；分数的方差全部被解读成趋势，噪声驱动决策。门禁要同时防这两种：评估必须在环，但决策必须预注册。</p><p><span class="marginnote">「预注册」就是把「什么情况触发什么动作」在看到数据之前写成条款，像体检报告的参考区间先于抽血定好；事后看到分数再决定怎么解读，等于没有门禁。</span></p><h3 id="门禁的三层判据" tabindex="-1">门禁的三层判据 <a class="header-anchor" href="#门禁的三层判据" aria-label="Permalink to &quot;门禁的三层判据&quot;">​</a></h3><p>第一层，<strong>趋势判据</strong>：训练 CE 对 token 的斜率是否符合<a href="/llm/loss-curve-phases">幂律段</a>预期——偏离预期才触发调查，不是触发调参。第二层，<strong>能力判据</strong>：低频跑固定的探针集（数学、代码、多语言、阅读各一小簇），检查能力结构是否随配比意图成形；探针集在开工前与评测隔离一起定死，见<a href="/llm/pf2-pretrain-checklist">检查清单</a>。第三层，<strong>健康判据</strong>：上一课的信号带——update/weight 比、梯度范数、吞吐——门禁把信号升级为决策。三层各有触发动作：调查（只查不改）、重估（换口径再测一次）、调整（动配方，须显式升版并记录对照损失）。</p>',8)),(B(),t(s,null,{default:a(()=>[r(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%B8%AD%E9%80%94%E8%AF%84%E4%BC%B0%E7%82%B9%EF%BC%88%E6%AF%8F%20N%20token%EF%BC%89%22%5D%20--%3E%20T%7B%22%E8%B6%8B%E5%8A%BF%E5%88%A4%E6%8D%AE%EF%BC%9ACE%20%E6%96%9C%E7%8E%87%E5%9C%A8%E5%B8%A6%E5%86%85%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%E5%90%A6%7C%20I%5B%22%E8%B0%83%E6%9F%A5%EF%BC%9A%E5%8F%AA%E6%9F%A5%E4%B8%8D%E6%94%B9%22%5D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20C%7B%22%E8%83%BD%E5%8A%9B%E5%88%A4%E6%8D%AE%EF%BC%9A%E6%8E%A2%E9%92%88%E7%BB%93%E6%9E%84%E6%88%90%E5%BD%A2%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20R%5B%22%E9%87%8D%E4%BC%B0%E5%8F%A3%E5%BE%84%20%2B%20%E6%A0%B8%E5%AF%B9%E9%85%8D%E6%AF%94%22%5D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20H%7B%22%E5%81%A5%E5%BA%B7%E5%88%A4%E6%8D%AE%EF%BC%9A%E4%BF%A1%E5%8F%B7%E5%B8%A6%E6%AD%A3%E5%B8%B8%EF%BC%9F%22%7D%0A%20%20H%20--%3E%7C%E5%90%A6%7C%20A%5B%22%E5%A4%84%E7%BD%AE%E8%B5%B0%E5%B0%96%E5%B3%B0%E9%A2%84%E6%A1%88%22%5D%0A%20%20H%20--%3E%7C%E6%98%AF%7C%20GO%5B%22%E7%BB%A7%E7%BB%AD%EF%BC%8C%E5%88%B0%E4%B8%8B%E4%B8%80%E4%B8%AA%E8%AF%84%E4%BC%B0%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行口径三条。第一，<strong>频率与预算</strong>：探针评估的频率按决策需要定，不是按好奇心定；每次评估的卡时计入算力账，因为评估占用的机器就是训练让出的机器。第二，<strong>轨迹契约</strong>：评估是旁路设施，开与关的逐步损失必须逐点重合——评估作业不得写回训练存储、不得占用使数据流水线饿死的带宽，这正是设施课不变量在配方层的应用。第三，<strong>决策留痕</strong>：每个评估点的结论写进跟踪库（run 身份四元组不变），「继续」也要写，否则事后无法区分「没评估」与「评估了没问题」。</p><p><span class="marginnote">中途探针的分数量级要提前讲给团队：四选一基准的 25% 是瞎猜线，幂律段的早期模型可能长期贴着它爬——把 25% 附近的起伏当趋势，是中途门禁最常见的误读。</span></p><p><span class="marginnote">数字实例：全程 2T token、每 100B 跑一次探针，共 20 个评估点；每次探针 500 卡时，合计 1 万卡时，只占总预算的零头。但若改成「每 5B 跑全量榜单」，评估账就会反过来吃掉训练本体。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么判据要预注册：中途决策的诱惑在于事后解释永远好写——「分数降了所以我们调整了」无法被证伪。预注册把可证伪的判据放在观测之前，调整从「兴奋决策」变成「触发条款」。为什么评估要低频：评估本身改变被评对象的环境——占资源、拖进度，更重要的是高频评估的方差会制造不存在的趋势，让团队把功率谱里的噪声读成信号。为什么「只查不改」是一层：调查与调整的混淆会绕过配方冻结——中途改配比必须走数据耗尽一课那样的显式通道，带对照与升版，而不是借一次门禁顺手改。</p><p><span class="marginnote">常见误区：初学者容易把探针分数的每次起伏都读成趋势。小探针集的分数方差本来就大，相邻两点的差常常纯属抽样噪声；趋势要看跨多个评估点的方向，不是看单点涨跌。</span></p>',7)),(B(),t(s,null,{default:a(()=>[r(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%9F%90%E6%8E%A2%E9%92%88%E5%88%86%E6%95%B0%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20B%7B%22%E9%A2%84%E6%B3%A8%E5%86%8C%E5%88%A4%E6%8D%AE%E8%A2%AB%E8%A7%A6%E5%8F%91%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%E6%B2%A1%E8%A7%A6%E5%8F%91%7C%20C%5B%22%E5%8F%AA%E6%9F%A5%E4%B8%8D%E6%94%B9%EF%BC%9A%E6%A0%B8%E5%AF%B9%E5%8F%A3%E5%BE%84%E4%B8%8E%E9%85%8D%E6%AF%94%22%5D%0A%20%20B%20--%3E%7C%E8%A7%A6%E5%8F%91%E4%BA%86%7C%20D%7B%22%E5%8A%A8%E5%93%AA%E6%9D%A1%E5%90%88%E6%B3%95%E9%80%9A%E9%81%93%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%E6%95%B0%E6%8D%AE%E4%BE%A7%7C%20E%5B%22%E5%86%8D%E9%85%8D%E6%AF%94%EF%BC%9A%E6%98%BE%E5%BC%8F%E5%8D%87%E7%89%88%20%2B%20%E5%AF%B9%E7%85%A7%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20D%20--%3E%7C%E7%BB%93%E6%9E%84%E4%BE%A7%7C%20F%5B%22%E7%BB%93%E6%9E%84%E6%94%B9%E5%8A%A8%EF%BC%9A%E6%98%BE%E5%BC%8F%E5%8D%87%E7%89%88%22%5D%0A%20%20D%20--%3E%7C%E9%83%BD%E4%B8%8D%E9%80%82%E7%94%A8%7C%20G%5B%22%E6%9C%AC%E6%AC%A1%E4%B8%8D%E8%AE%B8%E5%8A%A8%EF%BC%9A%E7%AD%89%E4%B8%8B%E4%B8%80%E8%AF%84%E4%BC%B0%E7%82%B9%22%5D%0A%20%20C%20--%3E%20H%5B%22%E7%BB%93%E8%AE%BA%E7%95%99%E7%97%95%E8%BF%9B%E8%B7%9F%E8%B8%AA%E5%BA%93%22%5D%0A%20%20E%20--%3E%20H%0A%20%20F%20--%3E%20H%0A%20%20G%20--%3E%20H%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p>这张图回答的是「分数异动之后哪些动作合法」：先问触发条款，再走两条显式升版通道，其余一律只查不改——这与第一张图的判据层互补。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的门禁决定「这次训练怎么走」，不是「这个模型好不好」——候选模型的发布门禁在模型评估门禁一课，判据密度完全不同。探针集的设计与去污属于评测工程，本课只要求它开工前锁定；评测框架的版本绑定见<a href="/llm/eval-harness">评测工具链</a>。曲线怎么画、口径怎么统一，见<a href="/llm/ti-loss-curve-reading">loss 曲线的解读</a>。健康信号本身的机理上一课已写。最后，门禁触发的调整只有两条合法通道：数据侧的再配比（数据耗尽一课）与结构侧的显式升版；学习率日程不在中途调整之列——那是日程契约课的边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中途门禁答「继续、调整还是停下」，不是答「涨了几分」。</li><li>三层判据：趋势（CE 斜率对带）、能力（探针结构）、健康（信号带）；各有触发动作。</li><li>评估是旁路设施：不写回训练存储、不占垮流水线，逐步损失与不开它逐点重合。</li><li>决策留痕，「继续」也要写；中途改配方只走显式升版通道。</li><li>出处：Kaplan et al., 2020 与 Nakkiran et al., 2020 的曲线分期口径；据大规模训练门禁实践整理。</li></ul>',5))])}const c=n(C,[["render",p]]);export{f as __pageData,c as default};
